def migrate_flat_bindings(apps, schema_editor):
    """把 0020 的扁平绑定（车间+类型+设备→多表）转成绑定树。

    0020 的车间是 production_line 外键；新树的车间只是查询分组，
    因此按**车间名称**落到自己的表里。转换后旧表由 DeleteModel 删除。
    """
    Old = apps.get_model("energy", "EnergyMeterBinding")
    Workshop = apps.get_model("energy", "MeterBindingWorkshop")
    Type = apps.get_model("energy", "MeterBindingType")
    Device = apps.get_model("energy", "MeterBindingDevice")
    Assignment = apps.get_model("energy", "MeterBindingAssignment")

    for old in Old.objects.select_related("energy_type", "workshop").prefetch_related("meters"):
        ws, _ = Workshop.objects.get_or_create(
            name=old.workshop.line_name,
            defaults={"sort": old.workshop.sort},
        )
        btype, _ = Type.objects.get_or_create(
            workshop=ws,
            energy_type_id=old.energy_type_id,
            name=old.usage_type,
            defaults={"sort": old.sort},
        )
        device, _ = Device.objects.get_or_create(
            type=btype,
            name=old.device_name,
            defaults={"sort": old.sort},
        )
        for idx, meter in enumerate(old.meters.all()):
            Assignment.objects.get_or_create(
                device=device,
                meter_id=meter.id,
                defaults={"sort": idx},
            )


def restore_flat_bindings(apps, schema_editor):
    """反向迁移（尽力而为）：新树的车间能按名称匹配回 production_line 才能还原。

    自定义车间名在旧模型里没有对应外键，只能跳过；这属于新功能回退的已知限制。
    """
    Old = apps.get_model("energy", "EnergyMeterBinding")
    Workshop = apps.get_model("energy", "MeterBindingWorkshop")
    ProductionLine = apps.get_model("energy", "ProductionLine")

    for ws in Workshop.objects.prefetch_related(
        "types__devices__assignments", "types__energy_type"
    ):
        line = ProductionLine.objects.filter(
            node_type="workshop", line_name=ws.name
        ).first()
        if line is None:
            continue
        for btype in ws.types.all():
            for device in btype.devices.all():
                old, _ = Old.objects.get_or_create(
                    energy_type_id=btype.energy_type_id,
                    workshop_id=line.id,
                    usage_type=btype.name,
                    device_name=device.name,
                    defaults={"sort": device.sort},
                )
                old.meters.set([a.meter_id for a in device.assignments.all()])


